INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template) VALUES
  (40, 1, '이미지와 컨테이너의 차이 구분하기', 'Docker 를 처음 쓸 때 가장 헷갈리는 두 낱말입니다. **이미지**와 **컨테이너**의 관계로 알맞은 것은 무엇일까요?', '요리에 비유하면 이미지는 "레시피와 재료 세트", 컨테이너는 그것으로 "만든 요리"입니다.', NULL, NULL, '[]', 'choice', '["이미지는 실행 중인 프로세스이고, 컨테이너는 그것을 저장한 파일이다", "이미지는 컨테이너를 만들기 위한 읽기 전용 설계도(템플릿)이고, 컨테이너는 그 이미지를 실행한 것이다", "이미지와 컨테이너는 같은 것을 부르는 다른 이름이다", "컨테이너는 이미지가 아닌 가상 머신 파일이다"]', 1, '**이미지**는 컨테이너를 만들 때 쓰는 읽기 전용 템플릿입니다. 같은 이미지로 **컨테이너**를 여러 개 실행할 수 있고, 각 컨테이너는 서로 독립된 실행 상태를 가집니다.', NULL, NULL),
  (40, 2, '이미지를 받아 컨테이너를 실행하고 정리하는 순서대로 놓기', 'nginx 이미지로 컨테이너를 실행하고 정리하는 명령이 섞여 있습니다. **일반적인 작업 순서**대로 놓으세요.', '이미지를 받고, 컨테이너로 실행하고, 확인한 뒤, 멈추고, 지웁니다. 실행 중인 컨테이너는 먼저 멈춰야 지울 수 있습니다.', NULL, NULL, '[]', 'order', '["`docker stop web` 으로 멈추기", "`docker ps` 로 실행 중인 컨테이너 확인", "`docker run -d --name web nginx` 로 컨테이너 실행", "`docker rm web` 으로 컨테이너 지우기", "`docker pull nginx` 로 이미지 내려받기"]', NULL, '`pull`(이미지 받기) → `run`(컨테이너 실행) → `ps`(확인) → `stop`(멈추기) → `rm`(컨테이너 지우기) 순서입니다. `docker run` 은 이미지가 없으면 자동으로 받기도 하지만, 단계를 구분해 익히기 위한 흐름입니다.', '[4, 2, 1, 0, 3]', NULL),
  (40, 3, '-p 옵션으로 포트 연결하는 빈칸 채우기', '내 컴퓨터의 **8080 포트**로 접속하면 컨테이너 안 nginx 의 **80 포트**로 연결되도록 명령의 빈칸을 채우세요.', '`-p 내컴퓨터포트:컨테이너포트` 순서입니다. nginx 는 컨테이너 안에서 80 포트를 씁니다.', NULL, NULL, '[]', 'fill', '["8080", "80", "443", "3306"]', NULL, '`-p 호스트포트:컨테이너포트` 입니다. `8080:80` 은 내 컴퓨터 8080 으로 온 요청을 컨테이너의 80 으로 보냅니다. 그러면 `http://localhost:8080` 으로 접속해 nginx 가 응답합니다.', '[0, 1]', 'docker run -d --name web -p {0}:{1} nginx'),
  (40, 4, 'docker ps 와 docker ps -a 의 차이 알기', '컨테이너를 멈춘 뒤 `docker ps` 를 실행했더니 목록에 보이지 않습니다. 멈춘 컨테이너까지 보려면 어떻게 해야 할까요?', '`docker ps` 는 기본으로 **실행 중인** 컨테이너만 보여 줍니다. 전부 보여 달라는 옵션이 있습니다.', NULL, NULL, '[]', 'choice', '["`docker ps -a` (all 의 약자, 멈춘 컨테이너까지 모두 보여 준다)", "`docker ps -r` (running 만 보여 준다)", "`docker images` (컨테이너 목록을 보여 준다)", "멈춘 컨테이너는 자동으로 지워져서 볼 수 없다"]', 0, '`docker ps` 는 실행 중인 컨테이너만, `docker ps -a` 는 멈춘(종료된) 컨테이너까지 모두 보여 줍니다. 멈춘 컨테이너는 직접 `docker rm` 으로 지우기 전까지 남아 있습니다. `docker images` 는 이미지 목록입니다.', NULL, NULL),
  (40, 5, '컨테이너를 지우면 안의 데이터가 어떻게 되는지 알기', '컨테이너 안에서 파일을 만들어 두었습니다. 그 컨테이너를 `docker rm` 으로 지우면 그 파일은 어떻게 될까요? 그리고 데이터를 남기려면 무엇을 써야 할까요?', '컨테이너의 쓰기 공간은 컨테이너와 함께 사라집니다. 컨테이너 밖에 따로 보관하는 저장소가 필요합니다.', NULL, NULL, '[]', 'choice', '["그대로 남는다", "컨테이너와 함께 사라진다. 남기려면 볼륨(volume)이나 바인드 마운트를 쓴다", "이미지에 자동으로 저장된다", "`docker rm` 은 데이터를 지우지 않고 이름만 지운다"]', 1, '컨테이너 안에서 쓴 파일은 그 컨테이너의 쓰기 공간에 저장돼서 컨테이너를 지우면 같이 사라집니다. 데이터를 남기려면 컨테이너 밖에 보관하는 **볼륨**(`-v 이름:/경로`)이나 호스트 폴더를 연결하는 **바인드 마운트**를 씁니다.', NULL, NULL),
  (40, 6, '레지스트리가 하는 일 알기', 'Docker Hub 같은 **레지스트리**는 무엇을 하는 곳일까요?', '`docker pull` 은 어디서 이미지를 내려받을까요? `docker push` 는 어디로 올릴까요?', NULL, NULL, '[]', 'choice', '["컨테이너를 실행하는 서버를 빌려 준다", "이미지를 저장하고 공유하는 저장소다 (`pull` 로 받고 `push` 로 올린다)", "컨테이너 안의 로그를 모아 보여 준다", "Dockerfile 을 자동으로 만들어 준다"]', 1, '레지스트리는 이미지를 저장하고 공유하는 곳입니다. `docker pull` 로 내려받고 `docker push` 로 올립니다. 회사 안에서 쓰는 사설 레지스트리도 같은 방식으로 동작합니다.', NULL, NULL),
  (40, 7, '레지스트리에서 이미지만 내려받는 명령 채우기', 'Docker Hub 에서 `nginx:1.25` 이미지를 **내려받기만** 하고 컨테이너는 실행하지 않으려고 합니다. 명령의 빈칸을 채우세요.', '이미지를 내려받는 하위 명령 하나만 필요합니다. 올리는 명령, 만드는 명령, 실행하는 명령과 헷갈리지 마세요.', NULL, NULL, '[]', 'fill', '["pull", "push", "build", "run"]', NULL, '`docker pull` 은 레지스트리에서 이미지를 내려받기만 합니다. `push` 는 올리기, `build` 는 Dockerfile 로 이미지 만들기, `run` 은 컨테이너 실행입니다.', '[0]', 'docker {0} nginx:1.25'),
  (40, 8, '가상 머신과 컨테이너의 차이 알기', '컨테이너가 가상 머신(VM)보다 가볍고 빠르게 시작되는 가장 큰 이유는 무엇일까요?', 'VM 은 게스트 운영체제를 통째로 하나 더 띄웁니다. 컨테이너는 무엇을 함께 쓸까요?', NULL, NULL, '[]', 'choice', '["컨테이너는 하드웨어를 직접 제어한다", "컨테이너는 호스트의 커널을 공유해서 운영체제를 따로 띄우지 않는다", "컨테이너는 파일을 압축해서 쓴다", "컨테이너는 CPU 를 사용하지 않는다"]', 1, 'VM 은 가상 하드웨어 위에 게스트 운영체제 전체를 띄우지만, 컨테이너는 **호스트의 커널을 공유**하고 프로세스를 격리해서 실행합니다. 그래서 크기가 작고 시작이 빠릅니다. 대신 호스트 커널과 같은 종류의 운영체제만 쓸 수 있습니다.', NULL, NULL);
